def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(
        remaining >= 0,
        np.floor_divide(remaining, item) - 1e-10 * np.sqrt(bins),
        -1e9 * (item - bins)
    )
